# -*- coding: utf-8 -*-
from taf.playwright.sbts.interface import sbts


class FakePage(object):
    pass


class FakeBrowserSession(object):
    def __init__(self):
        self.page = FakePage()
        self.closed = False

    def close(self):
        self.closed = True


class FakeBrowserManager(object):
    instances = []

    def __init__(self, **kwargs):
        self.kwargs = kwargs
        self.session = FakeBrowserSession()
        self.instances.append(self)

    def create_session(self):
        return self.session


class FakeProvider(object):
    requested_versions = []

    @classmethod
    def provide(cls, version=None):
        cls.requested_versions.append(version)
        return FakeFacade


class FakeFacade(object):
    instances = []

    def __init__(self, session, screenshot_dir=None):
        self.session = session
        self.screenshot_dir = screenshot_dir
        self.login_kwargs = None
        self.logout_timeout = None
        self.closed = False
        self.instances.append(self)

    def login(self, **kwargs):
        self.login_kwargs = kwargs
        return None

    def logout(self, timeout=10):
        self.logout_timeout = timeout

    def get_bts_status(self, timeout=5):
        return "ACTIVE:{}".format(timeout)

    def save_screenshot(self, filename, screenshot_dir=None):
        return "{}/{}.png".format(screenshot_dir or self.screenshot_dir, filename)

    def close(self):
        self.closed = True
        self.session.close()


def test_interface_login_stores_named_facade_and_passes_options(tmp_path):
    FakeBrowserManager.instances = []
    FakeProvider.requested_versions = []
    FakeFacade.instances = []
    library = sbts(browser_manager_factory=FakeBrowserManager, provider=FakeProvider)

    result = library.login(
        "https://sbts.example",
        "Nemuadmin",
        "nemuuser",
        version="SBTS26R3",
        browser="firefox",
        alias="sbts1",
        headless=False,
        download_dir=str(tmp_path / "downloads"),
        screenshot_dir=str(tmp_path / "screenshots"),
        port=8443,
        ssl=False,
        readonly=True,
        timeout=12,
    )

    assert result is None
    assert FakeProvider.requested_versions == ["SBTS26R3"]
    assert FakeBrowserManager.instances[0].kwargs["browser"] == "firefox"
    assert FakeBrowserManager.instances[0].kwargs["headless"] is False
    facade = library._sessions.get("sbts1")
    assert facade is FakeFacade.instances[0]
    assert facade.login_kwargs["url"] == "https://sbts.example"
    assert facade.login_kwargs["port"] == 8443
    assert facade.login_kwargs["ssl"] is False
    assert facade.login_kwargs["readonly"] is True
    assert facade.login_kwargs["timeout"] == 12


def test_interface_delegates_status_screenshot_and_logout(tmp_path):
    FakeBrowserManager.instances = []
    FakeProvider.requested_versions = []
    FakeFacade.instances = []
    library = sbts(browser_manager_factory=FakeBrowserManager, provider=FakeProvider)
    library.login(
        "https://sbts.example",
        "Nemuadmin",
        "nemuuser",
        alias="sbts1",
        screenshot_dir=str(tmp_path),
    )

    assert library.get_bts_status(timeout=7, sbts="sbts1") == "ACTIVE:7"
    assert library.save_screenshot("after_login", sbts="sbts1").endswith("after_login.png")

    facade = library._sessions.get("sbts1")
    library.logout(timeout=3, sbts="sbts1")

    assert facade.logout_timeout == 3
    assert facade.closed is True
    assert facade.session.closed is True
    assert library.list_aliases() == []
